// Problem: Find the first duplicate number in an array
// Input: int[] nums = {2, 5, 3, 2, 8}
// Expected output: 2

public class DuplicateFinder {
    public static void main(String[] args) {
        var nums = new int[]{2, 5, 3, 2, 8};

        // Step 1: Understand - restate in comments
        // "Need to return first number that appears twice"
        // "If no duplicates, what do I return? (Ask interviewer!)"

        // Step 2: Trace example manually
        // Index 0: seen={2}, no duplicate yet
        // Index 1: seen={2,5}, no duplicate yet  
        // Index 2: seen={2,5,3}, no duplicate yet
        // Index 3: seen has 2 already -> return 2

        // Step 3: NOW write the actual solution
        var seen = new java.util.HashSet<Integer>();
        for (int num : nums) {
            if (seen.contains(num)) {
                System.out.println("First duplicate: " + num);
                return;
            }
            seen.add(num);
        }
        System.out.println("No duplicates found");
    }
}

// Problem: Find indices of two numbers that add up to target
// Input: nums = [2, 7, 11, 15], target = 9
// Output: [0, 1] because nums[0] + nums[1] = 2 + 7 = 9

import java.util.*;

public class TwoSumSolver {

    // Brute force: check every pair - O(n^2) time, O(1) space
    public int[] twoSumBruteForce(int[] nums, int target) {
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] + nums[j] == target) {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{}; // not found
    }

    // Optimized: use HashMap to avoid nested loop - O(n) time, O(n) space
    public int[] twoSumOptimized(int[] nums, int target) {
        var seen = new HashMap<Integer, Integer>(); // value -> index
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (seen.containsKey(complement)) {
                return new int[]{seen.get(complement), i};
            }
            seen.put(nums[i], i); // store for future lookups
        }
        return new int[]{};
    }
}

// Problem: Find top 3 most frequent words in a text
// Decomposed into 3 sub-tasks

import java.util.*;
import java.util.stream.*;

public class WordFrequencyAnalyzer {

    // Sub-task 1: Parse text into clean words
    public List<String> parseWords(String text) {
        return Arrays.stream(text.toLowerCase().split("\\s+"))
                .filter(word -> !word.isEmpty())
                .toList();
    }

    // Sub-task 2: Count frequency of each word
    public Map<String, Long> countFrequencies(List<String> words) {
        return words.stream()
                .collect(Collectors.groupingBy(
                    word -> word,
                    Collectors.counting()
                ));
    }

    // Sub-task 3: Extract top N most frequent
    public List<String> getTopN(Map<String, Long> frequencies, int n) {
        return frequencies.entrySet().stream()
                .sorted(Map.Entry.<String, Long>comparingByValue().reversed())
                .limit(n)
                .map(Map.Entry::getKey)
                .toList();
    }

    // Main method combines all sub-tasks
    public List<String> findTopWords(String text, int n) {
        var words = parseWords(text);              // Step 1
        var frequencies = countFrequencies(words); // Step 2
        return getTopN(frequencies, n);            // Step 3
    }
}

// Scenario 1: Check if array contains duplicates -> HashSet for O(1) lookup
public boolean hasDuplicates(int[] nums) {
    var seen = new HashSet<Integer>();
    for (int num : nums) {
        if (seen.contains(num)) return true; // O(1) check
        seen.add(num);
    }
    return false;
}

// Scenario 2: Count word frequencies -> HashMap for key-value pairs
public Map<String, Integer> wordFrequencies(List<String> words) {
    var freq = new HashMap<String, Integer>();
    for (var word : words) {
        freq.put(word, freq.getOrDefault(word, 0) + 1); // O(1) update
    }
    return freq;
}

// Scenario 3: Always process smallest element -> PriorityQueue (min-heap)
public int findKthSmallest(int[] nums, int k) {
    var minHeap = new PriorityQueue<Integer>();
    for (int num : nums) {
        minHeap.offer(num); // maintains sorted order
    }
    for (int i = 1; i < k; i++) {
        minHeap.poll(); // remove k-1 smallest
    }
    return minHeap.peek(); // kth smallest is now at top
}

// Scenario 4: Reverse a string -> Stack for LIFO
public String reverseString(String s) {
    var stack = new Stack<Character>();
    for (char c : s.toCharArray()) stack.push(c);
    var reversed = new StringBuilder();
    while (!stack.isEmpty()) reversed.append(stack.pop());
    return reversed.toString();
}

// Problem: Find duplicate numbers in an array
public List<Integer> findDuplicates(int[] nums) {
    var seen = new HashSet<Integer>();  // Space: O(n) auxiliary storage
    var duplicates = new ArrayList<Integer>();

    for (int num : nums) {  // Time: O(n) single pass
        if (seen.contains(num)) {  // O(1) HashSet lookup
            duplicates.add(num);
        } else {
            seen.add(num);  // O(1) HashSet insertion
        }
    }
    return duplicates;
}

// After writing, state explicitly:
// "Time complexity is O(n) because we iterate through the array once,
//  and HashSet operations are O(1) average case.
// Space complexity is O(n) in worst case when all elements are unique,
//  requiring storage for the entire set."
